export type IconName = keyof typeof GLYPHS;
export type IconProps = { size?: number | string } & Omit<SVGProps<SVGSVGElement>, "name">;
export type IconComponent = (props: IconProps) => ReactNode;

/** App-wide icon. Colors follow currentColor; size via `size` or a className like size-4. */
export function Icon({ name, size = 16, strokeWidth: _strokeWidth, ...rest }: IconProps & { name: IconName }) {
  const glyph: Glyph = GLYPHS[name];
  return (
    <svg width={size} height={size} viewBox={glyph.vb ?? "0 0 24 24"} fill="currentColor" aria-hidden data-slot="icon" {...rest}>
      {glyph.body}
    </svg>
  );
}

function bind(name: IconName): IconComponent {
  const Bound = (props: IconProps) => <Icon {...props} name={name} />;
  Bound.displayName = `Icon(${name})`;
  return Bound;
}

/** Icon components by name, for places that pass an icon as a value (e.g. `icon: icons.check`). */
export const icons = Object.fromEntries(
  (Object.keys(GLYPHS) as IconName[]).map((name) => [name, bind(name)]),
) as Record<IconName, IconComponent>;

export const ICON_NAMES = Object.keys(GLYPHS) as IconName[];
export const ICON_SOURCES: Record<IconName, string> = Object.fromEntries(
  Object.entries(GLYPHS).map(([name, g]) => [name, (g as Glyph).src]),
) as Record<IconName, string>;
